class Song {
  + Title : string
  + Year : int
  + Length : int
  + Genre : string
}

class Artist {
  + Name : string
  + BirthDate : date
  + WebsiteURL : string
}

abstract class User {
  + UserID : int
  + Name : string
  + Address : string
}

class RegularUser extends User {}

class BusinessUser extends User {
  + VATNumber : string
}

class Single {}

class Hit {}

class Album {
}

class AlbumTrack {
  + TrackNumber : int
}

Artist "1" -- "*" Song : belongs to
BusinessUser "1" -- "*" Single : uploads
BusinessUser "1" -- "*" Hit : uploads
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : composes
Album "1" *-- "1..*" AlbumTrack : consists of
AlbumTrack "*" -- "1" Hit : refers to

@enduml

